using Nova.Core;
string root = Path.Combine(Path.GetTempPath(), "nova-test-" + Guid.NewGuid()); Directory.CreateDirectory(root);
try {
 void Assert(bool b, string m) { if (!b) throw new Exception(m); Console.WriteLine("OK " + m); }
 File.WriteAllText(Path.Combine(root,"film.mp4"), "x");
 File.WriteAllText(Path.Combine(root,"index.html"), "<html></html>");
 Assert(ProjectReader.Read(Path.Combine(root,"film.mp4")).Kind == WallpaperKind.Video, "video");
 Assert(ProjectReader.Read(root).Kind == WallpaperKind.Web, "web folder");
 File.WriteAllText(Path.Combine(root,"project.json"), "{\"title\":\"Scene\",\"type\":\"scene\",\"file\":\"scene.pkg\"}");
 Assert(ProjectReader.Read(root).Kind == WallpaperKind.Scene, "scene");
 File.WriteAllText(Path.Combine(root,"project.json"), "{\"type\":\"web\",\"file\":\"../outside.html\"}");
 bool blocked=false; try { ProjectReader.Read(root); } catch (InvalidDataException) { blocked=true; } Assert(blocked,"path traversal");
 File.WriteAllText(Path.Combine(root,"project.json"), "{\"title\":\"Web\",\"type\":\"web\",\"file\":\"index.html\",\"preview\":\"preview.png\"}");
 var web = ProjectReader.Read(root); Assert(web.Kind==WallpaperKind.Web && web.Title=="Web" && web.Entry.EndsWith("index.html"),"web project metadata");
 File.WriteAllText(Path.Combine(root,"project.json"), "{\"type\":\"application\",\"file\":\"app.exe\"}");
 Assert(ProjectReader.Read(root).Kind==WallpaperKind.Application,"application classified without execution");
 File.WriteAllText(Path.Combine(root,"project.json"), "{broken"); blocked=false; try { ProjectReader.Read(root); } catch (System.Text.Json.JsonException) { blocked=true; } Assert(blocked,"bad json");
 Assert(!System.Text.Json.JsonSerializer.Deserialize<Settings>("{}")!.DesktopSnowEnabled, "desktop snow opt-in by default");
 var winter = System.Text.Json.JsonSerializer.Serialize(new Settings { DesktopSnowEnabled=true, WindowSnowCaps=false });
 var readWinter=System.Text.Json.JsonSerializer.Deserialize<Settings>(winter)!;
 Assert(readWinter.DesktopSnowEnabled && !readWinter.WindowSnowCaps, "desktop snow settings round-trip");
 var appearance = System.Text.Json.JsonSerializer.Deserialize<Settings>("{}")!;
 Assert(appearance.AnimationsEnabled && !appearance.CompactNavigation, "appearance defaults for existing settings");
 var appearanceSaved = System.Text.Json.JsonSerializer.Serialize(new Settings { AnimationsEnabled=false, CompactNavigation=true });
 var appearanceRead = System.Text.Json.JsonSerializer.Deserialize<Settings>(appearanceSaved)!;
 Assert(!appearanceRead.AnimationsEnabled && appearanceRead.CompactNavigation, "appearance settings round trip");
 Assert(new Wallpaper { Kind=WallpaperKind.Video }.TypeIcon != new Wallpaper { Kind=WallpaperKind.Web }.TypeIcon, "card type icons differ");
 var favorite=new Wallpaper { Title="Закат", Kind=WallpaperKind.Video, Favorite=true, Preview="p.png" };
 Assert(LibraryFilter.Matches(favorite,"ЗАКАТ","Видео",true), "favorite filter works with search and type");
 Assert(!LibraryFilter.Matches(favorite,"закат","Веб",true) && !LibraryFilter.Matches(new Wallpaper { Title="Закат" },"закат","Все типы",true),"favorite filter excludes mismatches");
 string changed=""; favorite.PropertyChanged+=(_,e)=>changed=e.PropertyName; favorite.Preview="new.png"; Assert(changed=="Preview","thumbnail change notifies bindings");
 changed=""; favorite.Favorite=false; Assert(changed=="Favorite","favorite change notifies bindings");
 var savedFavorite=System.Text.Json.JsonSerializer.Serialize(new Wallpaper { Title="x", Favorite=true, Preview="cache.png" });
 var restoredFavorite=System.Text.Json.JsonSerializer.Deserialize<Wallpaper>(savedFavorite)!; Assert(restoredFavorite.Favorite && restoredFavorite.Preview=="cache.png", "favorite and thumbnail round trip");
 var uiDefault=System.Text.Json.JsonSerializer.Deserialize<Settings>("{}")!;
 Assert(uiDefault.AccentTheme==AccentTheme.Orange && uiDefault.AccentStrength==100 && !uiDefault.AutoThumbnails,"safe appearance and thumbnail defaults");
 var uiSaved=System.Text.Json.JsonSerializer.Serialize(new Settings { AccentTheme=AccentTheme.Mint,AccentStrength=60,AutoThumbnails=true }); var uiRead=System.Text.Json.JsonSerializer.Deserialize<Settings>(uiSaved)!;
 Assert(uiRead.AccentTheme==AccentTheme.Mint && uiRead.AccentStrength==60 && uiRead.AutoThumbnails,"theme and auto thumbnail round trip");
 Assert(ColorThemeRules.ClampStrength(0)==50 && ColorThemeRules.ClampStrength(200)==100 && ColorThemeRules.ClampStrength(70)==70,"accent strength bounds");
 var defaults = System.Text.Json.JsonSerializer.Deserialize<Settings>("{}")!;
 Assert(defaults.DesktopSeason == SeasonEffect.Snow && defaults.DesktopIntensity==100 && defaults.DesktopSpeed==100,"season defaults preserve old settings");
 var seasonal = System.Text.Json.JsonSerializer.Serialize(new Settings { DesktopSeason=SeasonEffect.Petals, DesktopIntensity=175, DesktopSpeed=50 });
 var seasonRead = System.Text.Json.JsonSerializer.Deserialize<Settings>(seasonal)!;
 Assert(seasonRead.DesktopSeason==SeasonEffect.Petals && seasonRead.DesktopIntensity==175 && seasonRead.DesktopSpeed==50,"season settings round trip");
 var id1=Guid.NewGuid(); var id2=Guid.NewGuid();
 var migrated=System.Text.Json.JsonSerializer.Deserialize<Settings>($"{{\"ActiveId\":\"{id1}\",\"Monitor\":\"screen1\"}}")!;
 WorkspaceRules.Migrate(migrated); Assert(migrated.MonitorAssignments!.Count==1 && migrated.MonitorAssignments[0].WallpaperId==id1,"migrate old single monitor assignment");
 WorkspaceRules.Assign(migrated,"screen2",id2); Assert(migrated.MonitorAssignments!.Count==2 && migrated.MonitorAssignments.Any(x=>x.Monitor=="screen1" && x.WallpaperId==id1),"independent monitor assignments");
 WorkspaceRules.Assign(migrated,"SCREEN1",id2); Assert(migrated.MonitorAssignments!.Count==2 && migrated.MonitorAssignments.Single(x=>x.Monitor.Equals("screen1",StringComparison.OrdinalIgnoreCase)).WallpaperId==id2,"replace only selected monitor");
 WorkspaceRules.Unassign(migrated,"screen1"); Assert(migrated.MonitorAssignments!.Count==1 && migrated.MonitorAssignments[0].Monitor=="screen2","stop one monitor preserves others");
 var roundtrip=System.Text.Json.JsonSerializer.Deserialize<Settings>(System.Text.Json.JsonSerializer.Serialize(migrated))!; WorkspaceRules.Migrate(roundtrip); Assert(roundtrip.MonitorAssignments!.Count==1 && roundtrip.MonitorAssignments[0].WallpaperId==id2,"multi-monitor persistence round trip");
 WorkspaceRules.Unassign(roundtrip,"screen2"); roundtrip.ActiveId=id1; WorkspaceRules.Migrate(roundtrip); Assert(roundtrip.MonitorAssignments!.Count==0,"empty assignments never resurrect legacy setting");
 for(int i=0;i<14;i++)WorkspaceRules.Remember(roundtrip,Guid.NewGuid()); WorkspaceRules.Remember(roundtrip,id1); WorkspaceRules.Remember(roundtrip,id1); Assert(roundtrip.RecentWallpapers.Count==12 && roundtrip.RecentWallpapers[0]==id1 && roundtrip.RecentWallpapers.Count(x=>x==id1)==1,"bounded distinct recents");
 WorkspaceRules.Assign(roundtrip,"s",id1); WorkspaceRules.RemoveWallpaper(roundtrip,id1); Assert(roundtrip.MonitorAssignments!.Count==0 && !roundtrip.RecentWallpapers.Contains(id1),"remove wallpaper clears assignments and history");
 var access=System.Text.Json.JsonSerializer.Deserialize<Settings>(System.Text.Json.JsonSerializer.Serialize(new Settings {AccessibleMode=true,LibraryLayout=LibraryLayout.List}))!; Assert(access.AccessibleMode && access.LibraryLayout==LibraryLayout.List,"accessibility and view round trip");
 Assert(CursorBackupRules.MatchesApplied(@"C:\a.cur",@"c:\A.CUR"), "cursor restore match ignores path case");
 Assert(!CursorBackupRules.MatchesApplied(@"C:\other.cur",@"C:\a.cur"), "cursor restore refuses external change");
 Assert(!CursorBackupRules.MatchesApplied("", ""), "empty cursor backup is not trusted");
 Assert(DesktopLayoutRules.PreserveLayeredStyle(0x00000020)==0x00080020, "preserve layered flag and other styles");
 Assert(DesktopLayoutRules.Classify(true,true,true)==DesktopLayoutKind.Raised, "raised desktop takes priority");
 Assert(DesktopLayoutRules.Classify(false,false,true)==DesktopLayoutKind.Classic, "classic desktop");
 Assert(DesktopLayoutRules.Classify(true,false,false)==DesktopLayoutKind.Missing, "incomplete desktop layout");
 Assert(TaskbarColorFormat.PackAbgr(0x11,0x22,0x33,0x44)==0x44332211u, "taskbar ABGR packing");
 Assert(System.Text.Json.JsonSerializer.Deserialize<Settings>("{}")!.SnowEnabled, "snow defaults on for existing settings");
 var snowOff = System.Text.Json.JsonSerializer.Serialize(new Settings { SnowEnabled = false });
 Assert(!System.Text.Json.JsonSerializer.Deserialize<Settings>(snowOff)!.SnowEnabled, "snow setting round-trip");
 Assert(System.Text.Json.JsonSerializer.Deserialize<Settings>("{}")!.GarlandEnabled, "garland defaults on for existing settings");
 var lightsOff = System.Text.Json.JsonSerializer.Serialize(new Settings { GarlandEnabled = false });
 Assert(!System.Text.Json.JsonSerializer.Deserialize<Settings>(lightsOff)!.GarlandEnabled, "garland setting round-trip");
} finally { Directory.Delete(root,true); }
